const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

/**
 * Cloud masking function for Sentinel-2.
 * Uses the QA60 band to mask clouds and cirrus.
 * @param {ee.Image} image Sentinel-2 image.
 * @return {ee.Image} Cloud-masked image.
 */
function maskS2clouds(image) {
  const qa = image.select('QA60');
  // Bits 10 and 11 are clouds and cirrus, respectively.
  const cloudBitMask = 1 << 10;
  const cirrusBitMask = 1 << 11;
  // Both flags should be set to zero, indicating clear conditions.
  const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
  return image.updateMask(mask).divide(10000)
      .select("B.*")
      .copyProperties(image, ["system:time_start"]);
}

/**
 * Adds an NDVI band to a Sentinel-2 image.
 * @param {ee.Image} image Input image.
 * @return {ee.Image} Image with NDVI band.
 */
function addNDVI(image) {
  const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
  return image.addBands(ndvi);
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Point of interest in the Taklamakan Desert near Hotan city.
  const geometry = ee.Geometry.Point([79.92, 37.11]).buffer(20000); // 20km buffer

  // Define the start and end periods for comparison.
  const startDateRange = ee.DateRange('2020-02-23', '2020-03-10');
  const endDateRange = ee.DateRange('2020-04-15', '2020-04-29');

  // 2. Data Acquisition & Pre-processing
  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry);

  const startCollection = s2Collection.filterDate(startDateRange).map(maskS2clouds).map(addNDVI);
  const endCollection = s2Collection.filterDate(endDateRange).map(maskS2clouds).map(addNDVI);

  // 3. Data Availability Check
  const startCount = startCollection.size().getInfo();
  const endCount = endCollection.size().getInfo();

  console.log(`Images found (Feb-Mar 2020): ${startCount}`);
  console.log(`Images found (Apr 2020): ${endCount}`);

  if (startCount === 0 || endCount === 0) {
    console.log("No images found for one or both periods.");
    console.log("A"); // The desert has no vegetation, so no increase is expected.
    return;
  }

  // Create median composites to reduce noise and remaining cloud artifacts.
  const startImage = startCollection.median();
  const endImage = endCollection.median();

  // 4. Calculation
  const scale = 1000; // Use a coarse scale to avoid timeouts over the large area.

  const startMean = startImage.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const endMean = endImage.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  // Check for valid pixels by running a count reducer.
  const startPixelCount = startImage.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const endPixelCount = endImage.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Valid Pixels (Feb-Mar 2020): ${startPixelCount}`);
  console.log(`Valid Pixels (Apr 2020): ${endPixelCount}`);

  if (startPixelCount === 0 || endPixelCount === 0) {
      console.log("No valid pixels remained after cloud masking for one or both periods.");
      console.log("C2");
      return;
  }

  const startVal = startMean.get('NDVI').getInfo();
  const endVal = endMean.get('NDVI').getInfo();

  // 5. Validation & Final Answer
  if (startVal === null || endVal === null) {
    console.log("Could not calculate mean NDVI. Result was null.");
    console.log("C3");
    return;
  }

  console.log(`Mean NDVI (Feb-Mar 2020): ${startVal.toFixed(4)}`);
  console.log(`Mean NDVI (Apr 2020): ${endVal.toFixed(4)}`);

  const difference = endVal - startVal;
  console.log(`Change in NDVI: ${difference.toFixed(4)}`);

  // A small positive change might be noise. We require a meaningful increase.
  // A threshold of 0.005 is used to account for sensor noise and atmospheric variation.
  if (difference > 0.005) {
    console.log("Evidence: A slight increase in NDVI was detected.");
    console.log("A");
  } else {
    console.log("Evidence: No significant increase in NDVI was detected.");
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log("D");
  }
}

initEE();
